'use strict';

const fs = require('fs');

function readUIntBE(buf, offset, size) {
  if (size === 1) return buf.readUInt8(offset);
  if (size === 2) return buf.readUInt16BE(offset);
  if (size === 4) return buf.readUInt32BE(offset);
  if (size === 8) return Number(buf.readBigUInt64BE(offset));

  let value = 0;
  for (let i = 0; i < size; i++) {
    value = value * 256 + buf[offset + i];
  }
  return value;
}

function readBigIntBE(buf, offset, size) {
  let value = 0n;
  for (let i = 0; i < size; i++) {
    value = (value << 8n) | BigInt(buf[offset + i]);
  }
  if (size > 0 && (buf[offset] & 0x80)) {
    value -= 1n << BigInt(size * 8);
  }
  return value;
}

function readInteger(buf, offset, info) {
  const size = 1 << info;
  if (info >= 3) {
    return Number(readBigIntBE(buf, offset, size));
  }

  let value = 0n;
  for (let i = 0; i < size; i++) {
    value = (value << 8n) | BigInt(buf[offset + i]);
  }
  return Number(value);
}

function readLength(buf, offset, info) {
  if (info !== 0xf) {
    return { length: info, dataOffset: offset };
  }

  const sizeSize = 1 << (buf[offset] & 0x3);
  return {
    length: readUIntBE(buf, offset + 1, sizeSize),
    dataOffset: offset + 1 + sizeSize
  };
}

function formatDate(secondsSince2001) {
  const epoch2001 = Date.UTC(2001, 0, 1, 0, 0, 0);
  const iso = new Date(epoch2001 + secondsSince2001 * 1000).toISOString();
  return iso.endsWith('.000Z') ? iso.slice(0, -5) + 'Z' : iso;
}

function parsePlist(buffer) {
  if (buffer.length < 40) {
    throw new Error('File is too short to be a binary plist');
  }
  if (buffer.toString('ascii', 0, 6) !== 'bplist') {
    throw new Error('Invalid binary plist header');
  }

  const trailerStart = buffer.length - 32;
  const offsetSize = buffer[trailerStart + 6];
  const refSize = buffer[trailerStart + 7];
  const numObjects = Number(buffer.readBigUInt64BE(trailerStart + 8));
  const topObject = Number(buffer.readBigUInt64BE(trailerStart + 16));
  const offsetTableStart = Number(buffer.readBigUInt64BE(trailerStart + 24));

  if (![1, 2, 4, 8].includes(offsetSize) || ![1, 2, 4, 8].includes(refSize)) {
    throw new Error('Unsupported integer size in trailer');
  }

  const offsets = [];
  for (let i = 0; i < numObjects; i++) {
    offsets.push(readUIntBE(buffer, offsetTableStart + i * offsetSize, offsetSize));
  }

  function readRef(offset) {
    return readUIntBE(buffer, offset, refSize);
  }

  function parseObject(offset) {
    if (offset < 0 || offset >= buffer.length) {
      throw new Error('Object offset out of bounds');
    }

    const marker = buffer[offset];
    const type = marker >> 4;
    const info = marker & 0x0f;
    const contentOffset = offset + 1;

    switch (type) {
      case 0x0:
        if (info === 0x0) return null;
        if (info === 0x8) return false;
        if (info === 0x9) return true;
        throw new Error('Unsupported primitive marker 0x' + marker.toString(16));

      case 0x1:
        return readInteger(buffer, contentOffset, info);

      case 0x2:
        if (info === 0x2) return buffer.readFloatBE(contentOffset);
        if (info === 0x3) return buffer.readDoubleBE(contentOffset);
        throw new Error('Unsupported real marker 0x' + marker.toString(16));

      case 0x3:
        if (info !== 0x3) {
          throw new Error('Unsupported date marker 0x' + marker.toString(16));
        }
        return formatDate(buffer.readDoubleBE(contentOffset));

      case 0x4: {
        const { length, dataOffset } = readLength(buffer, contentOffset, info);
        return buffer.subarray(dataOffset, dataOffset + length).toString('base64');
      }

      case 0x5: {
        const { length, dataOffset } = readLength(buffer, contentOffset, info);
        return buffer.toString('ascii', dataOffset, dataOffset + length);
      }

      case 0x6: {
        const { length, dataOffset } = readLength(buffer, contentOffset, info);
        let result = '';
        for (let i = 0; i < length; i++) {
          result += String.fromCharCode(buffer.readUInt16BE(dataOffset + i * 2));
        }
        return result;
      }

      case 0x8: {
        const size = info + 1;
        let uid = 0n;
        for (let i = 0; i < size; i++) {
          uid = (uid << 8n) | BigInt(buffer[contentOffset + i]);
        }
        return { __uid__: Number(uid) };
      }

      case 0xa:
      case 0xc: {
        const { length, dataOffset } = readLength(buffer, contentOffset, info);
        const result = [];
        for (let i = 0; i < length; i++) {
          const ref = readRef(dataOffset + i * refSize);
          result.push(parseObject(offsets[ref]));
        }
        return result;
      }

      case 0xd: {
        const { length, dataOffset } = readLength(buffer, contentOffset, info);
        const result = {};
        const valueRefsOffset = dataOffset + length * refSize;
        for (let i = 0; i < length; i++) {
          const keyRef = readRef(dataOffset + i * refSize);
          const valueRef = readRef(valueRefsOffset + i * refSize);
          const key = parseObject(offsets[keyRef]);
          if (typeof key !== 'string') {
            throw new Error('Dictionary key is not a string');
          }
          result[key] = parseObject(offsets[valueRef]);
        }
        return result;
      }

      default:
        throw new Error('Unsupported object marker 0x' + marker.toString(16));
    }
  }

  return parseObject(offsets[topObject]);
}

const inputPath = process.argv[2];
if (!inputPath) {
  console.error('Usage: node parse.js <input.plist>');
  process.exit(1);
}

try {
  const buffer = fs.readFileSync(inputPath);
  const result = parsePlist(buffer);
  process.stdout.write(JSON.stringify(result) + '\n');
} catch (error) {
  console.error('Error: ' + error.message);
  process.exit(1);
}
