import plistlib, json, base64
with open('/app/input.plist','rb') as f:
    p = plistlib.load(f)
def enc(o):
    if isinstance(o, bytes): return base64.b64encode(o).decode()
    if isinstance(o, plistlib.UID): return {'__uid__': o.data}
    if isinstance(o, dict): return {k: enc(v) for k,v in o.items()}
    if isinstance(o, list): return [enc(v) for v in o]
    if hasattr(o, 'isoformat'): return o.isoformat().replace('+00:00','Z')
    return o
print(json.dumps(enc(p), indent=2))
